import csv
import json
import sys
import io

def csv_to_jsonl(text):
    if not text or not text.strip():
        return ""

    # Find all newlines that are NOT inside quotes to determine record boundaries.
    boundaries = []
    in_quotes = False
    for i, char in enumerate(text):
        if char == '"':
            if i + 1 < len(text) and text[i+1] == '"':
                pass # doubled quote
            else:
                in_quotes = not in_quotes
        elif (char == '\n' or char == '\r') and not in_quotes:
            boundaries.append(i)

    records = []
    start = 0
    for b in boundaries:
        content_segment = text[start:b]
        if content_segment.strip():
            records.append((start, content_segment))
        # Move start to the character after the newline sequence
        if b < len(text) and text[b] == '\r' and b+1 < len(text) and text[b+1] == '\n':
            start = b + 2
        else:
            start = b + 1

    if start < len(text):
        content_segment = text[start:]
        if content_segment.strip():
            records.append((start, content_segment))

    if not records:
        return ""

    header = None
    first_record_idx = -1
    for i, (pos, segment) in enumerate(records):
        try:
            parsed = list(csv.reader(io.StringIO(segment), quotechar='"', doublequote=True))
            if parsed and parsed[0]:
                header = parsed[0]
                first_record_idx = i
                break
        except Exception:
            pass

    if first_record_idx == -1:
        return ""

    num_cols = len(header)
    output = []
    for i, (pos, segment) in enumerate(records):
        if i == first_record_idx:
            continue

        try:
            parsed = list(csv.reader(io.StringIO(segment), quotechar='"', doublequote=True))
            if not parsed or not parsed[0]:
                continue
            row = parsed[0]
            if len(row) != num_cols:
                line_num = 0
                j = 0
                while j < pos:
                    if text[j] == '\n':
                        line_num += 1
                    elif text[j] == '\r' and j+1 < pos and text[j+1] == '\n':
                        line_num += 1
                        j += 1
                    j += 1
                raise ValueError(f"line {line_num + 1}: field count differs from the header")

            obj = {}
            for idx, val in enumerate(row):
                obj[header[idx]] = val
            output.append(json.dumps(obj))
        except ValueError as e:
            raise e
        except Exception:
            pass

    return "\n".join(output) + ("\n" if output else "")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(0)
    try:
        with open(sys.argv[1], 'r', encoding='utf-8') as f:
            content = f.read()
        print(csv_to_jsonl(content), end='')
    except ValueError as e:
        sys.stderr.write(str(e) + "\n")
        sys.exit(2)
    except Exception:
        sys.exit(1)
